-- Doublure de structure pour la vue `v_material_stock`
-- (Voir ci-dessous la vue réelle)
--
CREATE TABLE `v_material_stock` (
`material_id` bigint(20) unsigned
,`material_code` varchar(50)
,`designation` varchar(180)
,`category_id` bigint(20) unsigned
,`brand` varchar(100)
,`model` varchar(120)
,`minimum_stock` decimal(12,2)
,`operational_status` enum('AVAILABLE','IN_MAINTENANCE','DAMAGED','RETIRED')
,`total_quantity` decimal(34,2)
,`is_below_minimum` int(1)
);

